  buildings:{data:()=>osmBuildingData,store:storeBuildings,render:renderBuildings,meta:refreshBuildingMeta},
  'land-cover':{data:()=>osmLandCoverData,store:storeLandCover,render:renderLandCover,meta:refreshLandCoverMeta},
  'paved-areas':{data:()=>osmPavedAreaData,store:storePavedAreas,render:renderPavedAreas,meta:refreshPavedAreaMeta},
  roads:{data:()=>osmRoadData,store:storeRoads,render:renderRoads,meta:refreshRoadMeta},
  infrastructure:{data:()=>osmInfrastructureData,store:storeInfrastructure,render:renderInfrastructure,meta:refreshInfrastructureMeta},
  'global-objects':{data:()=>globalObjectData,store:storeGlobalObjectOverrides,render:renderGlobalObjects,meta:refreshGlobalObjectMeta}
