map.on('click',e=>{if(mode!=='manual'&&recording?.mode!=='manual'&&!supportPlacement)return;if(recording)map.closePopup();if(supportPlacement){const target=[e.latlng.lng,e.latlng.lat];let object=state.tracks.find(item=>item.id===supportPlacement.objectId),snapped=object&&nearestPointOnLine(object.coordinates,target);if(supportPlacement.chooseNearest){const candidates=state.tracks.filter(item=>isPowerLineSymbol(manualObjectSymbol('line',item))&&!localObjectIsInactive(item)).map(item=>({object:item,snapped:nearestPointOnLine(item.coordinates,target)})).filter(candidate=>candidate.snapped).map(candidate=>({...candidate,distance:distanceMetres(target,candidate.snapped.coordinate)})).sort((a,b)=>a.distance-b.distance);if(candidates[0]?.distance<=30){object=candidates[0].object;snapped=candidates[0].snapped}else{object=null;snapped=null}}if(!object||!snapped){supportPlacement=null;return toast('Ingen kraftledning inom 30 meter från punkten')}object.supports=Array.isArray(object.supports)?object.supports:[];object.supports.push({id:crypto.randomUUID(),coordinates:snapped.coordinate,angleDegrees:snapped.angleDegrees,supportType:String(object.symbol)==='511'?'tower':'pole',largeMast:Boolean(supportPlacement.largeMast)});supportPlacement=null;markObjectManuallyModified(object);save();rerenderLocalObject('line',object);toast('Stolpen placerades exakt på kraftledningen');return}if(recording?.cat==='point'){addPoint(e.latlng,0,'manual',recording.type);recording=null;labels()}else if(recording?.mode==='manual'){currentCoords.push([e.latlng.lng,e.latlng.lat,0,Date.now(),null,null]);updateTemp()}});
