function quality(a){return a<=3?['excellent',`★ GPS ± ${Math.round(a)} m · Utmärkt`]:a<=10?['good',`GPS ± ${Math.round(a)} m · Bra`]:a<=50?['warn',`GPS ± ${Math.round(a)} m · Osäkert`]:['bad',`GPS ± ${Math.round(a)} m · Otillräckligt`]}
function refreshGpsButton(){const running=watchId!==null,button=$('#gpsQuality');button.setAttribute('aria-pressed',String(running));button.title=running?'Stäng av GPS':'Starta GPS';if(!running)button.querySelector('span').textContent='GPS av · Starta'}
function oneShotPosition(button,onSuccess){if(!navigator.geolocation)return toast('Positionering stöds inte av webbläsaren');if(button){button.disabled=true;button.classList.add('busy');button.setAttribute('aria-busy','true')}navigator.geolocation.getCurrentPosition(position=>{const latlng=L.latLng(position.coords.latitude,position.coords.longitude);lastPosition={latlng,accuracy:position.coords.accuracy};onSuccess(latlng,position.coords.accuracy);if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}},error=>{if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}toast(error.code===1?'Positionering saknar tillstånd':'Positionen kunde inte hämtas')},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
